//! numbers the real SDK headers give (Windows SDK 10.0.26100.0, x64).
//!
//! The assertions between the BEGIN/END markers are GENERATED by `tools/layout_check.c` (compiled with
//! MSVC `cl` against the headers; the regeneration steps are in that file's header comment). They are
//! not copied from the notes. If a test here fails, the Rust struct is wrong or the SDK changed: fix the
//! struct (or regenerate against the new SDK), never edit the numbers by hand.

use std::mem::size_of;

#[test]
fn pointer_size_is_x64() {
    // The generated numbers are for 64-bit Windows; a 32-bit or arm32 build would need its own run.
    assert_eq!(size_of::<usize>(), 8);
}

